<?php
namespace App\Filament\Widgets;
use App\Models\ContactEnquiry; use App\Models\Invoice; use App\Models\RequestDocument; use App\Models\ServiceRequest; use Filament\Widgets\StatsOverviewWidget as BaseWidget; use Filament\Widgets\StatsOverviewWidget\Stat;
class OperationsOverview extends BaseWidget { protected function getStats():array{return [Stat::make('Total requests',ServiceRequest::count())->description('All submitted requests')->color('primary'),Stat::make('New requests',ServiceRequest::where('status','new')->count())->description('Needs review')->color('warning'),Stat::make('Awaiting documents',ServiceRequest::where('status','awaiting_documents')->count())->description(RequestDocument::where('verification_status','pending')->count().' documents pending')->color('warning'),Stat::make('Completed',ServiceRequest::where('status','completed')->count())->description('Completed requests')->color('success'),Stat::make('Outstanding balance',number_format(Invoice::whereIn('status',['issued','partially_paid','overdue'])->sum(\Illuminate\Database\Query\Expression::raw('total - amount_paid')),2).' AED')->description('Open invoices')->color('danger'),Stat::make('New enquiries',ContactEnquiry::where('status','new')->count())->description('Contact follow-up')->color('info')];} }
